INSERT INTO grammar.content_catalog_topics(version,slug,catalog_hash,payload) VALUES('core-2026-09-v3','pronouns-and-possessive-determiners','e49c6c64b6333354230b05b223ded19e0e7519c1828bf3f36aee778f9f3f39c4','{"slug":"pronouns-and-possessive-determiners","title":"Pronouns and possession","level":"A1","order":3,"summary":"Distinguish subjects, objects, possessive determiners and possessive pronouns.","learningGoals":["Subject and object","Before a noun","Replacing a noun phrase"],"guidance":"Read the short rules and examples, then complete a 20-question session. Use feedback to explain each choice. Revisit the skill you missed before trying again.","rules":[{"title":"Subject and object","explanation":"Use I, he, she, we or they as subjects. Use me, him, her, us or them as objects. You and it keep the same form.","examples":["She invited us.","They spoke to me."]},{"title":"Before a noun","explanation":"Use my, your, his, her, its, our or their directly before a noun. These determiners identify the owner.","examples":["Our appointment is tomorrow.","Her parcel has arrived."]},{"title":"Replacing a noun phrase","explanation":"Mine, yours, his, hers, ours and theirs stand on their own. Do not add an apostrophe. His works both before a noun and on its own.","examples":["This seat is yours.","Those gloves are theirs."]}],"tips":["Read the full context before choosing.","Check the explanation, including after a correct answer.","A passing practice session is useful feedback, not a language certificate."],"source":"seed","provenance":{"version":"foundations-2026-09-v1","authorship":"Grammacho; generated offline with AI assistance","kind":"original-guidance-aligned","reviewStatus":"automated-checked; educator-review-pending","referenceIds":["bc-pronouns","bc-possessives","pcc-esol"],"assessment":"Practice only; levels are approximate teaching labels, not validated CEFR assessment."},"quizItems":[{"id":"81982cad-b99a-5c02-aa49-ba49bdd88c84","topicSlug":"pronouns-and-possessive-determiners","level":"A1","prompt":"Replace the object form with its subject form: “me”. ____ have an apple.","choices":[{"id":"A","text":"She"},{"id":"B","text":"I"},{"id":"C","text":"You"},{"id":"D","text":"He"}],"answerId":"B","hint":"Use I, he, she, we or they as subjects. Use me, him, her, us or them as objects. You and it keep the same form. Focus on **subject** in this question.","explanation":"The subject form paired with me is I. It performs the action of having the apple.","keywords":[],"source":"seed","skill":"subject","contextKey":"owner-apple","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-pronouns","bc-possessives","pcc-esol"],"version":"foundations-2026-09-v1","reviewStatus":"automated-checked; educator-review-pending"},"fingerprint":"2100f29bc9a248a7beb6799afebcf6df1e684c9268d4f48b75597f8505533a90","teaching":{"steps":["Identify what the question tests: **subject**. Use I, he, she, we or they as subjects. Use me, him, her, us or them as objects. You and it keep the same form.","The subject form paired with me is I. It performs the action of having the apple.","Choose **I**. Check the completed expression against the subject, time and intended meaning in the prompt."],"choiceReasons":{"A":"**She** can be a subject, but it refers to a different person or number from the one specified. The subject form paired with me is I. It performs the action of having the apple.","B":"The subject form paired with me is I. It performs the action of having the apple.","C":"**You** can be a subject, but it refers to a different person or number from the one specified. The subject form paired with me is I. It performs the action of having the apple.","D":"**He** can be a subject, but it refers to a different person or number from the one specified. The subject form paired with me is I. It performs the action of having the apple."}}},{"id":"2e6618b2-c872-5d1f-a359-5c1900b3108e","topicSlug":"pronouns-and-possessive-determiners","level":"A1","prompt":"Use the object form of “I”: The assistant handed ____ an apple.","choices":[{"id":"A","text":"him"},{"id":"B","text":"her"},{"id":"C","text":"me"},{"id":"D","text":"you"}],"answerId":"C","hint":"Use I, he, she, we or they as subjects. Use me, him, her, us or them as objects. You and it keep the same form. Focus on **object** in this question.","explanation":"After handed, use the object form me, not a possessive form.","keywords":[],"source":"seed","skill":"object","contextKey":"owner-apple","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-pronouns","bc-possessives","pcc-esol"],"version":"foundations-2026-09-v1","reviewStatus":"automated-checked; educator-review-pending"},"fingerprint":"d560985fc13c5d89377f1eb4871708f7f2622cd6b02bbfc4d4568faaf822aa50","teaching":{"steps":["Identify what the question tests: **object**. Use I, he, she, we or they as subjects. Use me, him, her, us or them as objects. You and it keep the same form.","After handed, use the object form me, not a possessive form.","Choose **me**. Check the completed expression against the subject, time and intended meaning in the prompt."],"choiceReasons":{"A":"**him** can be a object, but it refers to a different person or number from the one specified. After handed, use the object form me, not a possessive form.","B":"**her** can be a object, but it refers to a different person or number from the one specified. After handed, use the object form me, not a possessive form.","C":"After handed, use the object form me, not a possessive form.","D":"**you** can be a object, but it refers to a different person or number from the one specified. After handed, use the object form me, not a possessive form."}}},{"id":"be5af0cc-fe2e-5fdf-afe9-36d33ecf545f","topicSlug":"pronouns-and-possessive-determiners","level":"A1","prompt":"The apple belongs to me. Complete: This is ____ apple.","choices":[{"id":"A","text":"his"},{"id":"B","text":"her"},{"id":"C","text":"my"},{"id":"D","text":"your"}],"answ